const p1 = new Promise((resolve, reject) => {
    setTimeout(() => {
        resolve('promise1');
    }, 2000);
});

const p2 = new Promise((resolve, reject) => {
    setTimeout(() => {
        resolve('promise2');
    }, 5000);
});

async function some() {
    try {
        const res1 = await p1;
        console.log(res1);

        await new Promise(resolve => setTimeout(resolve, 5000));

        const res2 = await p2;
        console.log(res2);
    } catch (error) {
        console.log(error);
    }
}
some();

