function submitFormData(userInfo) {
  return new Promise((resolve, reject) => {
    fetch("https://jsonplaceholder.typicode.com/posts", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(userInfo),
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error("Network response was not ok!");
        }
        return response.json();
      })
      .then((data) => {
        localStorage.setItem("userInfo", JSON.stringify(userInfo));
        console.log("Response data stored in localStorage:", data);
        resolve(data);
        throw new Error("This is an error for testing purpose!")

      })
      .catch((error) => {
        document.getElementById("final").innerHTML =
        "Your form has been submitted successfully!";
        document.getElementById("hobbiesError").innerHTML = "";
        console.error("Error:", error.message);
        reject(error);
      });
  });
}

document.getElementById("submitButton").addEventListener("click", function () {
  if (validateForm(3)) {
    submitFormData(userInfo);
  }
});
